def shipped_requests(apps, schema_editor):
    """Let tenants and departments ask for the shipped case types that suit them, on existing installations."""
    from apps.cases.seed import request_defaults

    CaseType = apps.get_model("cases", "CaseType")
    for case_type in CaseType.objects.all():
        values = request_defaults(case_type.code)
        if values["tenant_can_start"] or values["department_can_start"]:
            for key, value in values.items():
                setattr(case_type, key, value)
            case_type.save()


